/// The semantic role of an identifier or literal node.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(u8)]
pub enum DataType {
    Whatever,
    TableName,
    ColumnName,
    ViewName,
    FunctionName,
    PragmaKey,
    PragmaValue,
    TableSpaceName,
    SequenceName,
    ExtensionName,
    RoleName,
    SchemaName,
    Database,
    TriggerName,
    WindowName,
    TriggerFunction,
    DomainName,
    AliasName,
    AliasTableName,
    Literal,
    IndexName,
    UserName,
    GroupName,
    DatabaseName,
    SystemName,
    ConversionName,
    AggregateArguments,
    NonReservedWord,
    FixLater,
    ConstraintName,
    RelOption,
    GenericType,
    TableNameFollow,
    ColumnNameFollow,
    Collate,
    StatisticName,
    ForeignTableName,
}

impl DataType {
    /// The C++ name without the `k` prefix, for example `DataTableName`.
    pub fn as_str(self) -> &'static str {
        DATA_TYPE_NAMES[self as usize]
    }
    pub fn from_str(name: &str) -> Option<DataType> {
        DATA_TYPE_NAMES.iter().position(|n| *n == name).map(|i| ALL_DATA_TYPES[i])
    }
}

